def context_precision(retrieved_chunks, relevant_chunk_ids):
    # applies the same discounted, position-aware scoring as NDCG
    relevant_positions = [
        position for position, chunk_id in enumerate(retrieved_chunks, start=1)
        if chunk_id in relevant_chunk_ids
    ]
    if not relevant_positions:
        return 0.0
    precision_at_each_hit = [
        sum(1 for p in relevant_positions if p <= hit_position) / hit_position
        for hit_position in relevant_positions
    ]
    return sum(precision_at_each_hit) / len(relevant_chunk_ids)

relevant = {"c1", "c3"}

# same relevant chunks, different positions
ordering_good = ["c1", "c3", "c2", "c4"]
ordering_bad = ["c2", "c4", "c1", "c3"]

print("Context precision by ordering:")
print(f"  Relevant chunks near the top: {context_precision(ordering_good, relevant):.3f}")
print(f"  Relevant chunks buried later: {context_precision(ordering_bad, relevant):.3f}")
